<?php
// Read all posted return history; correct only a proven, linked Good Item misclassification.
function rc_audit(){if(!in_array(access_profile(),['Admin','Operations Lead','Inventory Controller','Auditor'],true))throw new Exception('Return audit access required.');$rows=[];$counts=['Checked'=>0,'Correct'=>0,'Correctable'=>0,'Investigate'=>0];$batches=[];foreach(om_query("SELECT r.*,b.batch_ref,b.rows_json,b.status batch_status,p.master_sku,p.name FROM posted_returns r JOIN return_batches b ON b.id=r.batch_id JOIN products p ON p.id=r.product_id WHERE r.reversed=0 AND b.status='Posted' ORDER BY r.id") as $r){$source=null;$raw=$batches[$r['batch_id']]??=json_decode($r['rows_json'],true)?:[];foreach($raw as $line)if(hash('sha256','return|'.$r['batch_id'].'|'.($line['row']??0))===($r['dedupe_key']??'')){$source=$line;break;}if(!$source){$counts['Checked']++;$counts['Investigate']++;$rows[]=['return_id'=>(int)$r['id'],'batch'=>$r['batch_ref'],'platform'=>$r['platform'],'order'=>$r['original_ref'],'pid'=>(int)$r['product_id'],'sku'=>$r['master_sku'],'name'=>$r['name'],'qty'=>(int)$r['qty'],'state'=>'Investigate','reason'=>'Original condition evidence cannot be matched to this legacy receipt. Review the source document; no automatic stock correction.','kind'=>null];continue;}if(norm($source['condition']??'')!=='good item')continue;$counts['Checked']++;$q=(int)$r['qty'];$i=$r['inflow_id']?om_query('SELECT * FROM inflows WHERE id=?',[$r['inflow_id']])->fetch():null;$n=$r['non_sellable_id']?om_query('SELECT * FROM non_sellable WHERE id=?',[$r['non_sellable_id']])->fetch():null;$released=$n?release_total($n['id']):0;$nsLeft=$n?max(0,(int)$n['qty']-$released):0;$goodValid=$i&&$i['reversed_by_request']===null&&(int)$i['product_id']===(int)$r['product_id']&&(int)$i['qty']===$q&&$i['source_platform']===$r['platform'];$state='Investigate';$reason='Linked stock evidence is missing, changed or ambiguous. Do not add this quantity again.';$kind=null;
 if($goodValid&&(int)$r['good_qty']===$q&&(int)$r['damaged_qty']===0&&(int)$r['repackaging_qty']===0&&$nsLeft===0){$state='Correct';$reason='Good Item already credited to sellable. No stock correction needed.';}
 elseif($n&&$n['reversed_by_request']===null&&(int)$n['product_id']===(int)$r['product_id']&&(int)$n['qty']===$q&&$nsLeft===$q&&$released===0&&(int)$n['sellable_deducted']===0&&$n['origin']==='Order Return'&&($goodValid||(!$i&&(int)$r['good_qty']===0))){try{wc_ns_guard($n['id']);if(repack_active_source($n['id']))throw new Exception('Already assigned to repackaging.');check_platform_alignment($r['product_id']);$state='Correctable';$kind=$goodValid?'Remove duplicate Non-Sellable credit':'Reclassify Non-Sellable to sellable';$reason=$kind.'. Exact linked receipt only; original history retained.';}catch(Throwable $e){$reason='Protected / consumed source: '.$e->getMessage();}}
 $counts[$state]++;$rows[]=['return_id'=>(int)$r['id'],'batch'=>$r['batch_ref'],'platform'=>$r['platform'],'order'=>$r['original_ref'],'pid'=>(int)$r['product_id'],'sku'=>$r['master_sku'],'name'=>$r['name'],'qty'=>$q,'state'=>$state,'reason'=>$reason,'kind'=>$kind,'posted'=>$r,'inflow'=>$i?:null,'non_sellable'=>$n?:null,'released'=>$released];}return ['counts'=>$counts,'rows'=>$rows];}
function rc_plan($ids){if(!is_array($ids)||!$ids||count($ids)>20)throw new Exception('Review 1 to 20 verified historical corrections at a time.');$ids=array_values(array_unique(array_map('intval',$ids)));sort($ids,SORT_NUMERIC);$audit=rc_audit();$rows=[];$stock=[];foreach($audit['rows'] as $r)if(in_array($r['return_id'],$ids,true)){if($r['state']!=='Correctable')throw new Exception('A selected historical return no longer has an eligible linked correction.');$rows[]=$r;$s=stock_row($r['pid']);$stock[$r['pid']]=[$s['current'],$s['nonsellable'],$s['physical'],platform_qty($r['platform'],$r['pid'])];}if(count($rows)!==count($ids))throw new Exception('Selected historical Good Item return was not found.');$p=['ids'=>$ids,'rows'=>$rows,'stock'=>$stock];$p['digest']=hash('sha256',json_encode($p));return $p;}
function rc_apply($ids,$digest,$ack){if(current_user()['role']!=='Admin'||!$ack)throw new Exception('Admin must review and acknowledge the verified ledger corrections.');return process_transaction(function()use($ids,$digest){$sorted=array_values(array_unique(array_map('intval',$ids)));sort($sorted,SORT_NUMERIC);foreach($sorted as $id)om_query('SELECT id FROM posted_returns WHERE id=? FOR UPDATE',[$id])->fetch();$p=rc_plan($sorted);$products=array_keys($p['stock']);sort($products,SORT_NUMERIC);foreach($products as $pid)om_query('SELECT id FROM products WHERE id=? FOR UPDATE',[$pid])->fetch();foreach($p['rows'] as $r){om_query('SELECT id FROM non_sellable WHERE id=? FOR UPDATE',[$r['non_sellable']['id']])->fetch();if($r['inflow'])om_query('SELECT id FROM inflows WHERE id=? FOR UPDATE',[$r['inflow']['id']])->fetch();}$p=rc_plan($sorted);if(!hash_equals($p['digest'],(string)$digest))throw new Exception('Stock or historical receipt changed. Review the audit again.');$date=date('Y-m-d');require_open_inventory_date($date);foreach($p['rows'] as $r){$before=stock_row($r['pid']);$ref='RET-COND-'.$r['return_id'];$note='Verified Good Item correction; '.$r['batch'].' / '.$r['order'].'; original receipt retained';om_query('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)',[$date,$r['pid'],$r['qty'],'Return Condition Correction',$ref,$note,current_user()['id']]);$release=(int)db()->lastInsertId();om_query('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)',[$release,$r['non_sellable']['id'],$r['qty']]);$inflow=$r['inflow']['id']??null;if(!$inflow){om_query("INSERT INTO inflows(txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,'pc',?,'Return Condition Correction',?,?)",[$date,$ref,$r['order'],$r['platform'],$r['pid'],$r['qty'],$r['qty'],$note,current_user()['id']]);$inflow=(int)db()->lastInsertId();change_platform_stock($r['platform'],$r['pid'],$r['qty'],$ref,$date);}om_query('UPDATE posted_returns SET good_qty=qty,damaged_qty=0,repackaging_qty=0,inflow_id=? WHERE id=?',[$inflow,$r['return_id']]);check_platform_alignment($r['pid']);$after=stock_row($r['pid']);$delta=$r['kind']==='Remove duplicate Non-Sellable credit'?-$r['qty']:0;if($after['physical']!==$before['physical']+$delta)throw new Exception('Correction physical quantity did not reconcile.');$o=om_find($r['platform'],om_shops()[$r['platform']],$r['order']);om_event($o['id']??null,null,'Return condition corrected',['return_id'=>$r['return_id'],'batch'=>$r['batch'],'original_posted_record'=>$r['posted'],'original_non_sellable'=>$r['non_sellable'],'release_id'=>$release,'inflow_id'=>$inflow,'kind'=>$r['kind'],'before'=>['sellable'=>$before['current'],'non_sellable'=>$before['nonsellable'],'physical'=>$before['physical']],'after'=>['sellable'=>$after['current'],'non_sellable'=>$after['nonsellable'],'physical'=>$after['physical']],'reason'=>$note]);audit('Correct historical Good Item','Return',$ref,$r['kind'].'; '.$r['sku'].' x '.$r['qty'].'; '.$r['batch']);}return count($p['rows']);});}
function rc_assert_good_post($id,$condition){if($condition!=='Good Item')return;$r=om_query('SELECT r.*,i.qty inflow_qty,i.product_id inflow_product FROM posted_returns r LEFT JOIN inflows i ON i.id=r.inflow_id WHERE r.id=?',[$id])->fetch();if(!$r||$r['non_sellable_id']!==null||(int)$r['good_qty']!==(int)$r['qty']||(int)$r['damaged_qty']!==0||(int)$r['inflow_qty']!==(int)$r['qty']||(int)$r['inflow_product']!==(int)$r['product_id'])throw new Exception('Good Item did not post exclusively to sellable stock. Transaction rolled back.');}
function rc_reversal_guard($plan){foreach(array_merge($plan['inflows']??[],$plan['nonsellable_outflows']??[]) as $r)if(($r['type']??'')==='Return Condition Correction')throw new Exception('This is a linked historical return-condition correction. Do not reverse a single movement separately from its receipt.');foreach($plan['non_sellable']??[] as $n)if(om_query("SELECT COUNT(*) FROM nonsellable_release_links l JOIN nonsellable_outflows o ON o.id=l.release_id WHERE l.non_sellable_id=? AND o.type='Return Condition Correction' AND o.reversed_by_request IS NULL",[$n['id']])->fetchColumn())throw new Exception('This source has a linked return-condition correction. Preserve its correction trail.');}
function rc_destination($b,$line){if(($b['status']??'')!=='Posted')return ($line['condition']??'')==='Good Item'?'Sellable on confirmation':'Non-Sellable on confirmation';$r=om_query('SELECT * FROM posted_returns WHERE batch_id=? AND dedupe_key=? AND reversed=0',[$b['id'],hash('sha256','return|'.$b['id'].'|'.$line['row'])])->fetch();if(!$r)return 'Review linked stock record';if((int)$r['good_qty']>0&&$r['inflow_id'])return 'Sellable +'.$r['good_qty'].' · '.$r['platform'];if($r['non_sellable_id'])return ($line['condition']==='Good Item'?'Needs ledger audit · ':'').'Non-Sellable +'.((int)$r['damaged_qty']+(int)$r['repackaging_qty']);return 'Review linked stock record';}
function rc_page(){if(!access_page_allowed('return_audit'))throw new Exception('Return audit access required.');$a=rc_audit();echo '<h1>Good Item Return Audit</h1><p>Posted Good Item returns are checked against linked stock movements. Legacy receipts with missing condition evidence are listed for investigation. Good Item belongs in sellable stock, whether customer return or failed delivery. Correct records are never credited again.</p><div class="card"><div class="om-grid">';foreach($a['counts'] as $label=>$n)echo '<div><h3>'.$n.'</h3><p>'.e($label).'</p></div>';echo '</div></div><div class="card table-wrap"><table class="table"><tr><th>Receipt / Order</th><th>SKU / Qty</th><th>Audit result</th></tr>';$visible=array_values(array_filter($a['rows'],fn($r)=>$r['state']!=='Correct'));foreach(array_slice($visible,0,100) as $r)echo '<tr><td>'.e($r['batch'].' / '.$r['order']).'</td><td>'.e($r['sku']).' · '.$r['qty'].'</td><td>'.e($r['state'].' — '.$r['reason']).'</td></tr>';if(!$visible)echo '<tr><td colspan="3">No misclassified Good Item records found in the linked history.</td></tr>';echo '</table></div>';$eligible=array_slice(array_values(array_filter($a['rows'],fn($r)=>$r['state']==='Correctable')),0,20);if($eligible&&current_user()['role']==='Admin'){$p=rc_plan(array_column($eligible,'return_id'));echo '<div class="card"><h3>Review Verified Corrections</h3><p>Only the first '.count($p['rows']).' proven linked errors are included. Other records remain unchanged. Reclassification preserves physical quantity; removal of a proven duplicate removes only the duplicate Non-Sellable credit.</p><table class="table"><tr><th>SKU / Receipt</th><th>Action</th><th>Quantity</th></tr>';foreach($p['rows'] as $r)echo '<tr><td>'.e($r['sku'].' / '.$r['batch']).'</td><td>'.e($r['kind']).'</td><td>'.$r['qty'].'</td></tr>';echo '</table><form method="post" action="actions.php" data-confirm="Apply only these verified Good Item ledger corrections? Original receipt evidence will remain in history."><input type="hidden" name="action" value="receiving_correct_good_returns"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="return_ids" value="'.e(json_encode($p['ids'])).'"><input type="hidden" name="audit_digest" value="'.$p['digest'].'"><label><input type="checkbox" name="audit_ack" value="1" required> I reviewed the linked receipts, current stock effects and correction quantities.</label><button class="btn primary">Apply Verified Corrections</button></form></div>';}}
